        self.deletionGracePeriodDays = try container.decode(Int.self, forKey: .deletionGracePeriodDays)
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(deletionGracePeriodDays, forKey: .deletionGracePeriodDays)
    }
}

