        try container.encode(audience, forKey: .audience)
        try container.encodeIfPresent(authorizationHeader?.expose(), forKey: .authorizationHeader)
        try container.encodeIfPresent(clearAuthorizationHeader, forKey: .clearAuthorizationHeader)
        try container.encode(deliveryMethod, forKey: .deliveryMethod)
        try container.encodeIfPresent(description, forKey: .description)
        try container.encodeIfPresent(endpointURL, forKey: .endpointURL)
        try container.encode(eventsAllowed, forKey: .eventsAllowed)
        try container.encodeIfPresent(eventsRequested, forKey: .eventsRequested)
        try container.encode(receiverClientID, forKey: .receiverClientID)
        try container.encodeIfPresent(status, forKey: .status)
        try container.encodeIfPresent(statusReason, forKey: .statusReason)
        try container.encodeIfPresent(subjectFormat, forKey: .subjectFormat)
    }
}

/// A tenant is an isolated context within an organization. Each tenant has its own set of
/// users, roles, permissions, resources, certificates, and configuration. Tenants can represent
/// environments (dev/staging/prod) or separate business contexts.
public struct Tenant: Codable, Sendable {
    /// The server's `created_at` field.
    public let createdAt: String

    /// The server's `id` field.
    public let id: String

    /// Whether this is an ordinary tenant or the organization's own scope. `#[serde(default)]`
    /// so every row written before organization scope existed reads back as
    /// [`TenantKind::Standard`], which is what it is.
    public let kind: TenantKind?

    /// Arbitrary key-value metadata.
    public let metadata: ManagementJSON

    /// Human-readable name.
    public let name: String

    /// The organization this tenant belongs to.
    public let organizationID: String

    /// URL-safe unique identifier within the organization (e.g., `production`).
    public let slug: String

    /// Lifecycle status. New tenants default to [`TenantStatus::Active`].
    public let status: TenantStatus

    /// The server's `updated_at` field.
    public let updatedAt: String

    public init(
        createdAt: String,
        id: String,
        kind: TenantKind? = nil,
        metadata: ManagementJSON,
        name: String,
        organizationID: String,
        slug: String,
        status: TenantStatus,
        updatedAt: String
    ) {
        self.createdAt = createdAt
        self.id = id
        self.kind = kind
        self.metadata = metadata
        self.name = name
        self.organizationID = organizationID
        self.slug = slug
        self.status = status
        self.updatedAt = updatedAt
    }

    enum CodingKeys: String, CodingKey {
        case createdAt = "created_at"
        case id = "id"
        case kind = "kind"
        case metadata = "metadata"
        case name = "name"
        case organizationID = "organization_id"
        case slug = "slug"
        case status = "status"
        case updatedAt = "updated_at"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.createdAt = try container.decode(String.self, forKey: .createdAt)
        self.id = try container.decode(String.self, forKey: .id)
        self.kind = try container.decodeIfPresent(TenantKind.self, forKey: .kind)
        self.metadata = try container.decode(ManagementJSON.self, forKey: .metadata)
        self.name = try container.decode(String.self, forKey: .name)
        self.organizationID = try container.decode(String.self, forKey: .organizationID)
        self.slug = try container.decode(String.self, forKey: .slug)
        self.status = try container.decode(TenantStatus.self, forKey: .status)
        self.updatedAt = try container.decode(String.self, forKey: .updatedAt)
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(createdAt, forKey: .createdAt)
        try container.encode(id, forKey: .id)
        try container.encodeIfPresent(kind, forKey: .kind)
        try container.encode(metadata, forKey: .metadata)
        try container.encode(name, forKey: .name)
        try container.encode(organizationID, forKey: .organizationID)
        try container.encode(slug, forKey: .slug)
        try container.encode(status, forKey: .status)
        try container.encode(updatedAt, forKey: .updatedAt)
    }
}

