/// Per-tenant WebAuthn attestation policy (D5). One row per tenant; an absent row means
/// [`WebauthnAttestationPolicy::default`], which is today's behavior unchanged.
public struct WebauthnAttestationPolicy: Codable, Sendable {
    /// `None` = every AAGUID is allowed except `blocked_aaguids`. `Some(vec![])` is a
    /// deliberate "nothing may register" policy and is accepted as such: `evaluate` denies
    /// every AAGUID against an empty allow-list. Nothing rejects it, precisely because the
    /// failure direction is safe — a client that sends `[]` when it meant `null` gets a
    /// locked-down tenant, which is visible immediately, rather than an open one, which is not.
    public let allowedAaguids: [String]?

    /// Deny registration if the MDS entry has ever reported `REVOKED` or any `*_COMPROMISE`
    /// status (sticky — D8 step 7).
    public let blockRevokedStatus: Bool

    /// The server's `blocked_aaguids` field.
    public let blockedAaguids: [String]?

    /// The server's `min_certification` field.
    public let minCertification: CertificationLevel?

    /// The server's `mode` field.
    public let mode: AttestationMode

    /// Require *some* `FIDO_CERTIFIED*` status, any level. Independent of (and checked before)
    /// `min_certification`.
    public let requireFidoCertified: Bool

    /// The server's `unknown_aaguid` field.
    public let unknownAaguid: UnknownAaguidAction?

    public init(
        allowedAaguids: [String]? = nil,
        blockRevokedStatus: Bool,
        blockedAaguids: [String]? = nil,
        minCertification: CertificationLevel? = nil,
        mode: AttestationMode,
        requireFidoCertified: Bool,
        unknownAaguid: UnknownAaguidAction? = nil
    ) {
        self.allowedAaguids = allowedAaguids
        self.blockRevokedStatus = blockRevokedStatus
        self.blockedAaguids = blockedAaguids
        self.minCertification = minCertification
        self.mode = mode
        self.requireFidoCertified = requireFidoCertified
        self.unknownAaguid = unknownAaguid
    }

    enum CodingKeys: String, CodingKey {
        case allowedAaguids = "allowed_aaguids"
        case blockRevokedStatus = "block_revoked_status"
        case blockedAaguids = "blocked_aaguids"
        case minCertification = "min_certification"
        case mode = "mode"
        case requireFidoCertified = "require_fido_certified"
        case unknownAaguid = "unknown_aaguid"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.allowedAaguids = try container.decodeIfPresent([String].self, forKey: .allowedAaguids)
        self.blockRevokedStatus = try container.decode(Bool.self, forKey: .blockRevokedStatus)
        self.blockedAaguids = try container.decodeIfPresent([String].self, forKey: .blockedAaguids)
        self.minCertification = try container.decodeIfPresent(CertificationLevel.self, forKey: .minCertification)
        self.mode = try container.decode(AttestationMode.self, forKey: .mode)
        self.requireFidoCertified = try container.decode(Bool.self, forKey: .requireFidoCertified)
        self.unknownAaguid = try container.decodeIfPresent(UnknownAaguidAction.self, forKey: .unknownAaguid)
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encodeIfPresent(allowedAaguids, forKey: .allowedAaguids)
        try container.encode(blockRevokedStatus, forKey: .blockRevokedStatus)
        try container.encodeIfPresent(blockedAaguids, forKey: .blockedAaguids)
        try container.encodeIfPresent(minCertification, forKey: .minCertification)
        try container.encode(mode, forKey: .mode)
        try container.encode(requireFidoCertified, forKey: .requireFidoCertified)
        try container.encodeIfPresent(unknownAaguid, forKey: .unknownAaguid)
    }
}

/// WebAuthn ceremony policy. One field today. It is a struct rather than a bare field on
/// [`SecuritySettings`] so that the next WebAuthn control has an obvious home, and so the admin
/// UI can group them. The *attestation* policy is deliberately not here: it lives in
/// [`crate::models::webauthn_policy::WebauthnAttestationPolicy`], is tenant-only, and cannot
/// join this model because AAGUID allow/block lists have no "more restrictive than" ordering to
/// validate an override against. User verification does, so it can.
public struct WebauthnPolicy: Codable, Sendable {
    /// How hard the authenticator must prove *who* is present. Applies to enrolment and to
    /// second-factor authentication. Usernameless sign-in is held to `required` whatever this
    /// says — see [`WebauthnUserVerification`].
    public let webauthnUserVerification: String

    public init(
        webauthnUserVerification: String
    ) {
        self.webauthnUserVerification = webauthnUserVerification
    }

    enum CodingKeys: String, CodingKey {
        case webauthnUserVerification = "webauthn_user_verification"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.webauthnUserVerification = try container.decode(String.self, forKey: .webauthnUserVerification)
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(webauthnUserVerification, forKey: .webauthnUserVerification)
    }
}

